 void base(String title){screen=title;getWindow().setStatusBarColor(dark);getWindow().setNavigationBarColor(0xFFF3F7FC);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xFFF3F7FC);TextView head=text(english?(title.equals("ہوم")?"Sales & Profit ▥":"Sales & Profit  |  "+tx(title)):(title.equals("ہوم")?"سیلز و منافع ▥":"سیلز اور منافع  |  "+title),26,true);head.setTextColor(-1);head.setBackgroundColor(title.equals("ہوم")?0xFF086AC2:dark);head.setPadding(dp(22),dp(25),dp(22),dp(24));if(title.equals("ہوم")){head.setText(english?"Sales & Profit ▥\nMy Business, My Accounts":"سیلز و منافع ▥\nمیرا کاروبار، میرا حساب");head.setTextSize(23);head.setMinHeight(dp(118));}root.addView(head);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(dp(14),dp(12),dp(14),dp(18));body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(5),dp(5),dp(5),dp(5));nav.setBackgroundColor(-1);String[][] n={{"⌂\nہوم","home"},{"＋\nسیل","sale"},{"▦\nدکانیں","shops"},{"▣\nآئٹمز","items"},{"▤\nرپورٹس","reports"},{"⚙\nسیٹنگز","settings"}};for(String[] a:n){String[] parts=a[0].split("\\n");LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setGravity(Gravity.CENTER);item.setPadding(dp(2),dp(2),dp(2),dp(2));TextView ic=new TextView(this);ic.setText(parts[0]);ic.setTextSize(19);ic.setGravity(Gravity.CENTER);ic.setIncludeFontPadding(false);ic.setTextColor(a[1].equals(screen)?blue:0xFF657C9C);TextView label=new TextView(this);label.setText(parts.length>1?tx(parts[1]):"");if(!english&&nastaliq!=null)label.setTypeface(nastaliq);label.setTextSize(12);label.setGravity(Gravity.CENTER);if(english)label.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));label.setIncludeFontPadding(false);label.setSingleLine(true);label.setTextColor(a[1].equals(screen)?blue:0xFF657C9C);item.addView(ic,new LinearLayout.LayoutParams(-1,dp(25)));item.addView(label,new LinearLayout.LayoutParams(-1,dp(25)));item.setOnClickListener(v->navigate(a[1]));nav.addView(item,new LinearLayout.LayoutParams(0,dp(56),1));}hs.addView(nav);root.addView(hs);setContentView(root);}
