 void card(String title,String value){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(12),dp(16),dp(12));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(-1);bg.setCornerRadius(dp(22));bg.setStroke(dp(1),0xFFD9E6F7);c.setBackground(bg);c.addView(text(title,15,false));TextView val=text(value,23,true);val.setTextColor(ink);c.addView(val);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(10);body.addView(c,p);}
 LinearLayout panel(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(14),dp(14),dp(14),dp(14));android.graphics.drawable.GradientDrawable b=new android.graphics.drawable.GradientDrawable();b.setColor(-1);b.setCornerRadius(dp(24));b.setStroke(dp(1),0xFFD9E6F7);c.setBackground(b);return c;}
 void addStatGrid(String[][] data){for(int i=0;i<data.length;i+=2){LinearLayout row=new LinearLayout(this);row.setOrientation(0);for(int j=i;j<Math.min(i+2,data.length);j++){LinearLayout c=panel();TextView title=text(data[j][0],15,false);title.setGravity(Gravity.CENTER);title.setTextColor(0xFF587293);c.addView(title);TextView amount=text(data[j][1],24,true);amount.setGravity(Gravity.CENTER);amount.setTextColor(j==0?0xFF00965E:blue);c.addView(amount);TextView percent=text(data[j][3],14,true);percent.setGravity(Gravity.CENTER);percent.setTextColor(blue);c.addView(percent);TextView foot=text(data[j][2],13,false);foot.setGravity(Gravity.CENTER);foot.setTextColor(0xFF7186A3);c.addView(foot);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),0,dp(3),dp(10));row.addView(c,p);}body.addView(row,new LinearLayout.LayoutParams(-1,-2));}}
 void addTopShopsCard(){LinearLayout rank=panel();TextView heading=text("زیادہ منافع دینے والی دکانیں",20,true);heading.setGravity(Gravity.CENTER);heading.setTextColor(ink);rank.addView(heading);TextView hint=text("منتخب مہینے میں زیادہ منافع والی دکان پہلے دکھائی جائے گی",13,false);hint.setGravity(Gravity.CENTER);hint.setTextColor(0xFF7186A3);rank.addView(hint);String[] monthNames=english?new String[]{"January","February","March","April","May","June","July","August","September","October","November","December"}:new String[]{"جنوری","فروری","مارچ","اپریل","مئی","جون","جولائی","اگست","ستمبر","اکتوبر","نومبر","دسمبر"};LinearLayout filters=new LinearLayout(this);filters.setGravity(Gravity.CENTER_VERTICAL);Spinner month=new Spinner(this);month.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,monthNames));month.setSelection(Calendar.getInstance().get(Calendar.MONTH));Spinner year=new Spinner(this);ArrayList<String> ys=new ArrayList<>();int cy=Calendar.getInstance().get(Calendar.YEAR);for(int y=cy-5;y<=cy+2;y++)ys.add(""+y);year.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,ys));year.setSelection(5);filters.addView(month,new LinearLayout.LayoutParams(0,dp(48),1));filters.addView(year,new LinearLayout.LayoutParams(0,dp(48),1));rank.addView(filters);LinearLayout list=new LinearLayout(this);list.setOrientation(1);rank.addView(list);Runnable refresh=()->{list.removeAllViews();int yr=Integer.parseInt(year.getSelectedItem().toString()),mo=month.getSelectedItemPosition()+1;String df=String.format(Locale.US,"strftime('%%Y-%%m',s.created)='%04d-%02d'",yr,mo);Cursor c=db.getReadableDatabase().rawQuery("SELECT sh.name,COALESCE(SUM(s.total),0),COALESCE(SUM(s.profit),0) FROM shops sh LEFT JOIN sales s ON s.shop_id=sh.id AND "+df+" GROUP BY sh.id ORDER BY COALESCE(SUM(s.profit),0) DESC, sh.name LIMIT 10",null);int n=0;while(c.moveToNext()){LinearLayout item=new LinearLayout(MainActivity.this);item.setGravity(Gravity.CENTER_VERTICAL);item.setPadding(dp(8),dp(7),dp(8),dp(7));item.setOrientation(1);TextView name=text((n+1)+". "+c.getString(0),16,true);name.setTextColor(n==0?0xFF00965E:ink);item.addView(name);TextView value=text("پرافٹ: Rs. "+money(c.getDouble(2))+"   "+percentText(c.getDouble(1),c.getDouble(2)),16,true);value.setTextColor(0xFF00965E);item.addView(value);if(c.getDouble(2)<=0){TextView empty=text("اس مہینے ابھی منافع درج نہیں",12,false);empty.setTextColor(0xFF7186A3);item.addView(empty);}View divider=new View(MainActivity.this);divider.setBackgroundColor(0xFFE5EDF8);list.addView(item,new LinearLayout.LayoutParams(-1,-2));list.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));n++;}c.close();if(n==0)list.addView(text("ابھی کوئی دکان موجود نہیں",14,false));};android.widget.AdapterView.OnItemSelectedListener l=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> a){}};month.setOnItemSelectedListener(l);year.setOnItemSelectedListener(l);refresh.run();LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(14);body.addView(rank,p);}
 void showHome(){base("ہوم");LinearLayout hello=panel();TextView welcome=text("السلام علیکم! اپنے کاروبار کا منافع ایک نظر میں دیکھیں۔",18,true);if(!english&&naskh!=null)welcome.setTypeface(naskh,Typeface.BOLD);welcome.setTextColor(ink);hello.addView(welcome);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.bottomMargin=dp(14);body.addView(hello,hp);double[] today=db.summary("date(created)=date('now','localtime')");double[] week=db.summary("created>=date('now','-6 days','localtime')");double[] month=db.summary("strftime('%Y-%m',created)=strftime('%Y-%m','now','localtime')");double[] year=db.summary("strftime('%Y',created)=strftime('%Y','now','localtime')");addStatGrid(new String[][]{{"آج کا منافع","Rs. "+money(today[1]),"فروخت کا خلاصہ",percentText(today[0],today[1])},{"اس ہفتے کا منافع","Rs. "+money(week[1]),"فروخت کا خلاصہ",percentText(week[0],week[1])},{"اس مہینے کا منافع","Rs. "+money(month[1]),"فروخت کا خلاصہ",percentText(month[0],month[1])},{"اس سال کا منافع","Rs. "+money(year[1]),"فروخت کا خلاصہ",percentText(year[0],year[1])}});LinearLayout shortcuts=new LinearLayout(this);shortcuts.setOrientation(0);String[][] ss={{"▤","رپورٹس","reports"},{"▣","آئٹمز","items"},{"▦","دکانیں","shops"},{"＋","سیل درج کریں","sale"}};for(String[] a:ss){LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(3),dp(10),dp(3),dp(10));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(-1);bg.setCornerRadius(dp(20));bg.setStroke(dp(1),0xFFD9E6F7);tile.setBackground(bg);TextView ic=text(a[0],25,true);ic.setTextColor(blue);ic.setGravity(Gravity.CENTER);TextView label=text(a[1],13,true);if(!english&&nastaliq!=null)label.setTypeface(nastaliq);label.setGravity(Gravity.CENTER);label.setTextColor(ink);tile.addView(ic);tile.addView(label);tile.setOnClickListener(v->navigate(a[2]));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,dp(92),1);tp.setMargins(dp(3),0,dp(3),dp(14));shortcuts.addView(tile,tp);}body.addView(shortcuts,new LinearLayout.LayoutParams(-1,-2));addTopShopsCard();LinearLayout chart=new LinearLayout(this);chart.setOrientation(1);chart.setPadding(dp(16),dp(12),dp(16),dp(12));android.graphics.drawable.GradientDrawable cbg=new android.graphics.drawable.GradientDrawable();cbg.setColor(-1);cbg.setCornerRadius(dp(24));cbg.setStroke(dp(1),0xFFD9E6F7);chart.setBackground(cbg);TextView title=text("منافع کا رجحان                         گراف",20,true);if(!english&&nastaliq!=null)title.setTypeface(nastaliq);title.setTextColor(ink);chart.addView(title);LinearLayout tabs=new LinearLayout(this);tabs.setPadding(dp(4),dp(4),dp(4),dp(4));tabs.setBackgroundColor(0xFFEDF3FB);String[] ts={"روزانہ","ہفتہ وار","ماہانہ","سالانہ"};for(String t:ts){TextView tab=text(t,13,true);tab.setGravity(Gravity.CENTER);tab.setTextColor(t.equals("روزانہ")?-1:0xFF587293);if(t.equals("روزانہ"))tab.setBackgroundColor(blue);tabs.addView(tab,new LinearLayout.LayoutParams(0,dp(42),1));tab.setOnClickListener(v->{for(int j=0;j<tabs.getChildCount();j++){TextView z=(TextView)tabs.getChildAt(j);z.setBackgroundColor(z==tab?blue:0xFFEDF3FB);z.setTextColor(z==tab?-1:0xFF587293);}});}chart.addView(tabs);ProfitGraph graph=new ProfitGraph();chart.addView(graph,new LinearLayout.LayoutParams(-1,dp(155)));TextView total=text("کل منافع: Rs. "+money(db.summary("1=1")[1]),15,true);total.setGravity(Gravity.CENTER);total.setTextColor(0xFF00965E);chart.addView(total);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(14);body.addView(chart,cp);card("آج کی کل سیل",money(db.summary("date(created)=date('now','localtime')")[0])+" روپے");TextView recent=text("حالیہ سیلز",20,true);recent.setTextColor(ink);body.addView(recent);Cursor c=db.getReadableDatabase().rawQuery("SELECT date(s.created),sh.name,SUM(s.total),SUM(s.profit),SUM(sl.qty) FROM sales s JOIN shops sh ON sh.id=s.shop_id LEFT JOIN sale_lines sl ON sl.sale_id=s.id GROUP BY date(s.created),s.shop_id ORDER BY s.created DESC LIMIT 20",null);while(c.moveToNext()){LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setPadding(dp(16),dp(12),dp(16),dp(12));android.graphics.drawable.GradientDrawable ib=new android.graphics.drawable.GradientDrawable();ib.setColor(-1);ib.setCornerRadius(dp(22));ib.setStroke(dp(1),0xFFD9E6F7);item.setBackground(ib);TextView shopTitle=text(c.getString(1),18,true);if(!english)shopTitle.setTypeface(Typeface.create(nastaliq!=null?nastaliq:Typeface.DEFAULT,Typeface.BOLD));item.addView(shopTitle);TextView profit=text("Rs. "+money(c.getDouble(3))+"  "+percentText(c.getDouble(2),c.getDouble(3)),20,true);profit.setTextColor(0xFF00965E);item.addView(profit);item.addView(text("تاریخ: "+c.getString(0)+"  •  کل عدد: "+c.getInt(4),14,false));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,-2);ip.bottomMargin=dp(10);body.addView(item,ip);}c.close();}
 class ProfitGraph extends View{android.graphics.Paint p=new android.graphics.Paint(3);ProfitGraph(){super(MainActivity.this);}protected void onDraw(android.graphics.Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();p.setColor(0xFFE0EAF8);p.setStrokeWidth(dp(1));for(int i=1;i<=4;i++)c.drawLine(dp(12),h*i/5,w-dp(12),h*i/5,p);p.setColor(0xFF1680F8);p.setStrokeWidth(dp(3));float y=h*.72f;c.drawLine(dp(16),y,w-dp(16),y,p);p.setStyle(android.graphics.Paint.Style.FILL);for(int i=0;i<7;i++)c.drawCircle(dp(22)+i*(w-dp(44))/6,y,dp(4),p);}}
 void showSale(){base("نئی سیل");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM shops ORDER BY name",null);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();while(c.moveToNext()){ids.add(c.getInt(0));names.add(c.getString(1));}c.close();if(names.isEmpty()){body.addView(text("پہلے دکان شامل کریں",17,true));return;}shopSpinner=new Spinner(this);ArrayAdapter<String> shopAdapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,names){ TextView styleShop(View v){TextView t=(TextView)v;if(!english&&nastaliq!=null)t.setTypeface(Typeface.create(nastaliq,Typeface.BOLD));t.setTextSize(16);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;} @Override public View getView(int position,View convertView,android.view.ViewGroup parent){return styleShop(super.getView(position,convertView,parent));} @Override public View getDropDownView(int position,View convertView,android.view.ViewGroup parent){return styleShop(super.getDropDownView(position,convertView,parent));}};shopSpinner.setAdapter(shopAdapter);body.addView(text("دکان منتخب کریں",16,true));body.addView(shopSpinner);Cursor it=db.getReadableDatabase().rawQuery("SELECT id,name,cost,price FROM items ORDER BY name",null);ArrayList<Line> products=new ArrayList<>();while(it.moveToNext())products.add(new Line(it.getInt(0),it.getString(1),it.getDouble(2),it.getDouble(3)));it.close();lines=products;qtys=new EditText[lines.size()];prices=new EditText[lines.size()];for(int i=0;i<lines.size();i++){Line l=lines.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(4),0,dp(4));row.setBackgroundColor(-1);TextView nm=text(l.name,14,true);row.addView(nm,new LinearLayout.LayoutParams(0,-2,2));LinearLayout q=new LinearLayout(this);Button minus=new Button(this);minus.setText("−");qtys[i]=edit("0",true);qtys[i].setGravity(Gravity.CENTER);qtys[i].setInputType(InputType.TYPE_CLASS_NUMBER);final int ix=i;minus.setOnClickListener(v->{int x=val(qtys[ix]);qtys[ix].setText(""+Math.max(0,x-1));});Button plus=new Button(this);plus.setText("+");plus.setOnClickListener(v->{int x=val(qtys[ix]);qtys[ix].setText(""+(x+1));});q.addView(minus);q.addView(qtys[i],new LinearLayout.LayoutParams(dp(42),dp(48)));q.addView(plus);row.addView(q);prices[i]=edit(money(l.price),true);prices[i].setHint("قیمت");row.addView(prices[i],new LinearLayout.LayoutParams(dp(76),dp(48)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(4);body.addView(row,rp);View line=new View(this);line.setBackgroundColor(0xFFE0E8E5);body.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}body.addView(text("قیمت دکاندار کے مطابق تبدیل کر سکتے ہیں۔ خرید قیمت اسکرین پر نہیں دکھائی جاتی۔",13,false));body.addView(btn("سیل محفوظ کریں",()->saveSale(ids)));}
 int val(EditText e){try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception ex){return 0;}}
 void saveSale(ArrayList<Integer> ids){int shop=ids.get(shopSpinner.getSelectedItemPosition());ArrayList<Line> chosen=new ArrayList<>();double total=0,profit=0;for(int i=0;i<lines.size();i++){int q=val(qtys[i]);if(q<=0)continue;double p;try{p=Double.parseDouble(prices[i].getText().toString().replace(",","").trim());}catch(Exception e){p=lines.get(i).price;}Line l=lines.get(i);l.qty=q;l.price=p;chosen.add(l);total+=q*p;profit+=q*(p-l.cost);}if(chosen.isEmpty()){toast("کم از کم ایک آئٹم کی مقدار درج کریں");return;}SQLiteDatabase w=db.getWritableDatabase();ContentValues cv=new ContentValues();cv.put("shop_id",shop);cv.put("created",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(new Date()));cv.put("total",total);cv.put("profit",profit);long sid=w.insert("sales",null,cv);for(Line l:chosen){ContentValues v=new ContentValues();v.put("sale_id",sid);v.put("item_id",l.id);v.put("qty",l.qty);v.put("price",l.price);v.put("cost",l.cost);v.put("profit",l.qty*(l.price-l.cost));w.insert("sale_lines",null,v);}toast("سیل محفوظ ہو گئی");showHome();}
 void showShops(){base("دکانیں");EditText name=edit("",false);name.setHint("نئی دکان کا نام");body.addView(name);body.addView(btn("دکان شامل کریں",()->{String n=name.getText().toString().trim();if(!n.isEmpty()){ContentValues v=new ContentValues();v.put("name",n);db.getWritableDatabase().insert("shops",null,v);showShops();}}));Cursor c=db.getReadableDatabase().rawQuery("SELECT sh.id,sh.name,COALESCE(SUM(s.total),0),COALESCE(SUM(s.profit),0) FROM shops sh LEFT JOIN sales s ON s.shop_id=sh.id GROUP BY sh.id ORDER BY sh.name",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setBackgroundColor(-1);TextView shopTitle=text(c.getString(1),16,true);if(!english)shopTitle.setTypeface(Typeface.create(nastaliq!=null?nastaliq:Typeface.DEFAULT,Typeface.BOLD));row.addView(shopTitle);row.addView(text("کل سیل: "+money(c.getDouble(2))+" روپے   •   پرافٹ: "+money(c.getDouble(3))+" روپے "+percentText(c.getDouble(2),c.getDouble(3)),14,false));row.addView(btn("دکان حذف کریں",()->new AlertDialog.Builder(this).setMessage("کیا یہ دکان حذف کرنی ہے؟ اس کی سیلز بھی حذف ہوں گی۔").setNegativeButton("نہیں",null).setPositiveButton("ہاں، حذف",(d,w)->{db.deleteShop(id);showShops();}).show()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);body.addView(row,p);}c.close();}
 void showItems(){base("آئٹمز");EditText name=edit("",false);name.setHint("آئٹم کا نام");EditText cost=edit("",true);cost.setHint("خرید قیمت (صرف انتظام کے لیے)");EditText price=edit("",true);price.setHint("فروخت قیمت");body.addView(name);body.addView(cost);body.addView(price);body.addView(btn("آئٹم شامل کریں",()->{String n=name.getText().toString().trim();try{if(n.isEmpty())throw new Exception();ContentValues v=new ContentValues();v.put("name",n);v.put("cost",Double.parseDouble(cost.getText().toString()));v.put("price",Double.parseDouble(price.getText().toString()));db.getWritableDatabase().insert("items",null,v);showItems();}catch(Exception e){toast("نام، خرید اور فروخت قیمت درج کریں");}}));Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,cost,price FROM items ORDER BY name",null);while(c.moveToNext()){int id=c.getInt(0);LinearLayout r=new LinearLayout(this);r.setBackgroundColor(-1);r.setOrientation(1);r.addView(text(c.getString(1),16,true));r.addView(btn("ترمیم",()->editItem(id)));r.addView(btn("حذف",()->new AlertDialog.Builder(this).setMessage("آئٹم حذف کریں؟").setNegativeButton("نہیں",null).setPositiveButton("حذف",(d,w)->{db.getWritableDatabase().delete("items","id=?",new String[]{""+id});showItems();}).show()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(7);body.addView(r,p);}c.close();}
 void editItem(int id){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,cost,price FROM items WHERE id="+id,null);if(!c.moveToFirst()){c.close();return;}EditText n=edit(c.getString(0),false),co=edit(money(c.getDouble(1)),true),pr=edit(money(c.getDouble(2)),true);c.close();LinearLayout box=new LinearLayout(this);box.setPadding(dp(12),0,dp(12),0);box.setOrientation(1);box.addView(n);box.addView(co);box.addView(pr);new AlertDialog.Builder(this).setTitle("آئٹم میں ترمیم").setView(box).setNegativeButton("منسوخ",null).setPositiveButton("محفوظ",(d,w)->{try{ContentValues v=new ContentValues();v.put("name",n.getText().toString());v.put("cost",Double.parseDouble(co.getText().toString()));v.put("price",Double.parseDouble(pr.getText().toString()));db.getWritableDatabase().update("items",v,"id=?",new String[]{""+id});showItems();}catch(Exception e){toast("درست قیمت درج کریں");}}).show();}
 void showReports(){base("رپورٹس");body.addView(text("دکان وار منافع دیکھیں",18,true));Cursor sc=db.getReadableDatabase().rawQuery("SELECT id,name FROM shops ORDER BY name",null);ArrayList<Integer> shopIds=new ArrayList<>();ArrayList<String> shopNames=new ArrayList<>();shopIds.add(0);shopNames.add(english?"All shops":"تمام دکانیں");while(sc.moveToNext()){shopIds.add(sc.getInt(0));shopNames.add(sc.getString(1));}sc.close();Spinner shop=new Spinner(this);shop.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,shopNames));body.addView(shop);String[] monthNames=english?new String[]{"January","February","March","April","May","June","July","August","September","October","November","December"}:new String[]{"جنوری","فروری","مارچ","اپریل","مئی","جون","جولائی","اگست","ستمبر","اکتوبر","نومبر","دسمبر"};Spinner months=new Spinner(this);months.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,monthNames));months.setSelection(Calendar.getInstance().get(Calendar.MONTH));body.addView(text("مہینہ",14,true));body.addView(months);ArrayList<String> years=new ArrayList<>();int current=Calendar.getInstance().get(Calendar.YEAR);for(int y=current-5;y<=current+2;y++)years.add(""+y);Spinner year=new Spinner(this);year.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,years));year.setSelection(5);body.addView(text("سال",14,true));body.addView(year);Spinner period=new Spinner(this);period.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,english?new String[]{"Monthly report","Yearly report"}:new String[]{"ماہانہ رپورٹ","سالانہ رپورٹ"}));body.addView(period);LinearLayout results=new LinearLayout(this);results.setOrientation(1);body.addView(results);Runnable refresh=()->{results.removeAllViews();int yr=Integer.parseInt(year.getSelectedItem().toString());int mo=months.getSelectedItemPosition()+1;boolean monthly=period.getSelectedItemPosition()==0;String dateFilter=monthly?String.format(Locale.US,"strftime('%%Y-%%m',s.created)='%04d-%02d'",yr,mo):String.format(Locale.US,"strftime('%%Y',s.created)='%04d'",yr);int selected=shopIds.get(shop.getSelectedItemPosition());String where=dateFilter+(selected==0?"":" AND sh.id="+selected);Cursor sum=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(s.total),0),COALESCE(SUM(s.profit),0),COUNT(DISTINCT s.id) FROM sales s JOIN shops sh ON sh.id=s.shop_id WHERE "+where,null);sum.moveToFirst();cardInto(results,english?"Total sales":"کل سیل","Rs. "+money(sum.getDouble(0)));cardInto(results,english?"Total profit":"کل منافع","Rs. "+money(sum.getDouble(1))+"  "+percentText(sum.getDouble(0),sum.getDouble(1)));cardInto(results,english?"Orders":"آرڈرز",""+sum.getInt(2));sum.close();results.addView(text(english?"Profit by shop":"ہر دکان کا منافع",17,true));Cursor per=db.getReadableDatabase().rawQuery("SELECT sh.name,COALESCE(SUM(s.total),0),COALESCE(SUM(s.profit),0),COUNT(s.id) FROM shops sh LEFT JOIN sales s ON s.shop_id=sh.id AND "+dateFilter+(selected==0?"":" AND sh.id="+selected)+" GROUP BY sh.id ORDER BY SUM(s.profit) DESC",null);while(per.moveToNext()){LinearLayout p=panel();p.addView(text(per.getString(0),16,true));p.addView(text((english?"Sales: Rs. ":"کل سیل: Rs. ")+money(per.getDouble(1)),14,false));TextView profit=text((english?"Profit: Rs. ":"منافع: Rs. ")+money(per.getDouble(2))+"  "+percentText(per.getDouble(1),per.getDouble(2)),18,true);profit.setTextColor(0xFF00965E);p.addView(profit);p.addView(text((english?"Orders: ":"آرڈر: ")+per.getInt(3),13,false));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);results.addView(p,lp);}per.close();};body.addView(btn("رپورٹ دکھائیں",()->refresh.run()));android.widget.AdapterView.OnItemSelectedListener listener=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long id){refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> a){}};shop.setOnItemSelectedListener(listener);months.setOnItemSelectedListener(listener);year.setOnItemSelectedListener(listener);period.setOnItemSelectedListener(listener);refresh.run();}
 void cardInto(LinearLayout parent,String title,String value){LinearLayout c=panel();c.addView(text(title,14,true));TextView v=text(value,22,true);v.setTextColor(ink);c.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);parent.addView(c,p);}
