 String money(double d){return String.format(Locale.US,"%.0f",d);}String percentText(double sales,double profit){double cost=sales-profit;double pct=cost>0?profit*100.0/cost:0;return "٪"+String.format(Locale.US,"%.0f",pct); }void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 class DB extends SQLiteOpenHelper{DB(Context c){super(c,"sales_profit_urdu.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE shops(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL)");d.execSQL("CREATE TABLE items(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,cost REAL NOT NULL,price REAL NOT NULL)");d.execSQL("CREATE TABLE sales(id INTEGER PRIMARY KEY AUTOINCREMENT,shop_id INTEGER,created TEXT,total REAL,profit REAL)");d.execSQL("CREATE TABLE sale_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id INTEGER,item_id INTEGER,qty INTEGER,price REAL,cost REAL,profit REAL)");String[] ss=SHOPS;for(String s:ss){ContentValues v=new ContentValues();v.put("name",s);d.insert("shops",null,v);}Object[][] its=ITEMS;for(Object[] a:its){ContentValues v=new ContentValues();v.put("name",(String)a[0]);v.put("cost",(Integer)a[1]);v.put("price",(Integer)a[2]);d.insert("items",null,v);}}public void onUpgrade(SQLiteDatabase d,int a,int b){}int count(String t){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM "+t,null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}double[] summary(String where){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(total),0),COALESCE(SUM(profit),0) FROM sales WHERE "+where,null);c.moveToFirst();double[] a={c.getDouble(0),c.getDouble(1)};c.close();return a;}void deleteShop(int id){SQLiteDatabase w=getWritableDatabase();Cursor c=w.rawQuery("SELECT id FROM sales WHERE shop_id="+id,null);ArrayList<String> a=new ArrayList<>();while(c.moveToNext())a.add(c.getString(0));c.close();for(String sid:a)w.delete("sale_lines","sale_id=?",new String[]{sid});w.delete("sales","shop_id=?",new String[]{""+id});w.delete("shops","id=?",new String[]{""+id});}}
 static final String[] SHOPS = {"شہباز کریانہ سٹور", "ماسٹر کریانہ سٹور", "اعوان کریانہ سٹور", "گل نواز کریانہ سٹور", "نصر کریانہ سٹور", "برہان کریانہ سٹور", "عبد الرحمن کریانہ", "مہر کریانہ سٹور", "حرمین کریانہ سٹور", "ہادی کریانہ سٹور", "آصف کریانہ سٹور", "بلال کریانہ سٹور", "ملک کریانہ سٹور", "فرحت کریانہ سٹور", "العباس کریانہ سٹور", "الرحمن کریانہ سٹور", "حافظ ریحان کریانہ", "فیض کریانہ", "علی ڈسکاؤنٹ شاپ", "ظہور کریانہ", "علی سپر سٹور", "بابا کریانہ", "ظہور آگے کریانہ", "عطاء اللہ کریانہ", "نیو حافظ کریانہ", "ندیم کریانہ", "مہر زیشان کریانہ", "عبداللہ کریانہ", "اشرف کریانہ", "شیخ اسلم کریانہ", "ہادی پورہ کریانہ", "786 کریانہ"};
